export const icon=(name='star')=>{const paths={star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',signal:'<path d="M4 18v-4m5 4V9m5 9V5m5 13V2"/>',kit:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 13h18m-9-3v6"/>',boots:'<path d="M6 3h8v10l6 3v5H4V11h2z"/>',lamp:'<path d="m6 10 3-7h6l3 7zM12 10v10M6 21h12"/>',robot:'<rect x="4" y="6" width="16" height="14" rx="4"/><path d="M12 2v4M1 11h3m16 0h3M8 15h8"/><circle cx="8" cy="10" r="1"/><circle cx="16" cy="10" r="1"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M6 12h12"/>',plant:'<path d="M12 21V9M12 13C3 14 3 7 3 7s9-1 9 6m0-4c0-7 8-7 8-7s1 7-8 7M7 17h10l-2 5H9z"/>',cape:'<path d="m9 3-6 18 9-3 9 3-6-18zM9 3h6"/>',comic:'<path d="M3 3h18v15H9l-6 4zM7 8h10M7 12h7"/>',flag:'<path d="M5 22V2m0 1h14l-3 5 3 5H5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.star}</svg>`;};
export function robot(colour='#edaa50'){return `<svg viewBox="0 0 140 170" role="img" aria-label="Pip, your friendly robot sidekick"><ellipse cx="70" cy="157" rx="43" ry="7" fill="#193c3d" opacity=".12"/><path d="M42 105 32 142m65-37 12 37" stroke="#204951" stroke-width="14" stroke-linecap="round"/><path d="M32 86 15 108m92-23 16 23" stroke="#204951" stroke-width="12" stroke-linecap="round"/><rect x="35" y="82" width="69" height="49" rx="20" fill="${colour}"/><rect x="22" y="24" width="95" height="70" rx="23" fill="${colour}" stroke="#234a50" stroke-width="4"/><rect x="32" y="37" width="75" height="40" rx="14" fill="#163c44"/><circle cx="49" cy="55" r="7" fill="#b4e9c5"/><circle cx="90" cy="55" r="7" fill="#b4e9c5"/><path d="M61 67q9 8 18 0" fill="none" stroke="#b4e9c5" stroke-width="3" stroke-linecap="round"/><path d="M70 24V10" stroke="#234a50" stroke-width="5"/><circle cx="70" cy="8" r="6" fill="#ed7644"/><circle cx="70" cy="108" r="9" fill="#fff2c9"/><path d="m70 101-4 8h5l-2 7 8-11h-6l3-4" fill="#ed7644"/></svg>`;}
export function hero(colour='#ec7540',emblem='star',cape=true){let mark=emblem==='diamond'?'<path d="m100 112 10 13-10 13-10-13z"/>':emblem==='bolt'?'<path d="m101 110-12 17h10l-4 14 15-22h-10l5-9z"/>':'<path d="m100 111 4 9 10 1-7 7 2 10-9-5-9 5 2-10-7-7 10-1z"/>';return `<svg viewBox="0 0 200 240" role="img" aria-label="Your original Signal Scout hero"><ellipse cx="101" cy="228" rx="61" ry="8" fill="#122f36" opacity=".15"/>${cape?'<path d="M69 99 46 209l52-16 52 20-18-114z" fill="#e8c660"/>':''}<path d="m85 167-7 51m38-51 10 51" stroke="#173c45" stroke-width="22" stroke-linecap="round"/><path d="m69 110-23 40m84-40 22 40" stroke="${colour}" stroke-width="20" stroke-linecap="round"/><path d="M77 95h47l15 70q-37 17-76 0z" fill="${colour}"/><path d="M73 156h55" stroke="#183e43" stroke-width="9"/><rect x="95" y="153" width="12" height="8" rx="2" fill="#ffe193"/><g fill="#fff0be">${mark}</g><rect x="83" y="79" width="35" height="27" rx="10" fill="#bd805a"/><ellipse cx="101" cy="60" rx="37" ry="41" fill="#db9e70"/><path d="M64 60q-10-49 27-51 14-6 31 2 21 7 16 44l-16-25-11 13-25-12-17 31" fill="#173c45"/><path d="M65 57q36-16 72 0l-4 21q-15 10-31-2-19 12-34 0z" fill="#173c45"/><ellipse cx="84" cy="66" rx="8" ry="5" fill="#fff2c9"/><ellipse cx="119" cy="66" rx="8" ry="5" fill="#fff2c9"/><path d="M93 87q9 6 18 0" fill="none" stroke="#7a4d36" stroke-width="3" stroke-linecap="round"/><path d="M67 222H47m85 0h21" stroke="#173c45" stroke-width="14" stroke-linecap="round"/></svg>`;}
export function city(colour,emblem,done=0){return `<svg viewBox="0 0 630 330" role="img" aria-label="Your hero and robot overlooking the academy city"><circle cx="347" cy="158" r="127" fill="#f2efbc"/><g fill="none" stroke="#9fbca6" stroke-width="1" opacity=".5"><circle cx="347" cy="158" r="146"/><circle cx="347" cy="158" r="164"/></g><g fill="#b1cbb7"><path d="M0 260V172h49v88m5 0V132h62v128m5 0V187h40v73m320 0V144h49v116m7 0V178h46v82m7 0V124h44v136"/><path d="M82 131V107h7v24m417 12v-29h6v29"/></g><g fill="#789e88"><path d="M5 280V212h77v68m32 0V194h48v86m364 0V197h78v83m21 0V166h52v114"/></g><g fill="${done?'#f7db85':'#d6e6ce'}">${[20,44,124,140,494,518,555,578].map((x,i)=>`<rect x="${x}" y="${i<4?225:213}" width="8" height="13" rx="2"/>`).join('')}</g><path d="M0 288q188-39 315-13t315 0v55H0z" fill="#92b49b"/><path d="m135 330 88-53h167l112 53" fill="#d3dec0"/><g transform="translate(267 34) scale(1.1)">${hero(colour,emblem,done>=9).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g class="spark" transform="translate(167 151) scale(.72)">${robot().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g fill="#ed7841"><path d="m451 53 5 13 13 5-13 5-5 13-5-13-13-5 13-5z"/><circle cx="190" cy="67" r="4"/></g><g fill="#173c45" opacity=".4"><path d="m91 73 9-5 9 5-9-2zm426 29 9-5 9 5-9-2z"/></g></svg>`;}

export function pictureSteps(type){
 const speaker='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M12 25h12l14-12v38L24 39H12z" fill="#15786d"/><path d="M45 23q12 9 0 18m5-25q22 16 0 32" stroke="#15786d" stroke-width="4" fill="none" stroke-linecap="round"/></svg>';
 const tile='<svg viewBox="0 0 64 64" aria-hidden="true"><rect x="7" y="7" width="41" height="41" rx="10" fill="#d4e9db" stroke="#15786d" stroke-width="3"/><text x="27" y="36" text-anchor="middle" fill="#14353b" font-size="28" font-family="Arial">a</text><path class="tap-hand" d="M35 51V33q0-6 5-6t5 6v7l5-4 7 6-4 16H39z" fill="#f2b67b" stroke="#7d5639" stroke-width="2" stroke-linejoin="round"/></svg>';
 const swap='<svg viewBox="0 0 64 64" aria-hidden="true"><rect x="5" y="12" width="22" height="29" rx="5" fill="#d4e9db"/><rect x="37" y="12" width="22" height="29" rx="5" fill="#f9d27d"/><path d="M20 48h26m-7-7 7 7-7 7" stroke="#15786d" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
 const book='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M7 12q13-5 25 2 12-7 25-2v39q-13-5-25 2-12-7-25-2z" fill="#d4e9db" stroke="#15786d" stroke-width="3"/><path d="M32 14v39M13 23h12m-12 9h12m13-9h12m-12 9h12" stroke="#15786d" stroke-width="3"/></svg>';
 const tick='<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="25" fill="#15786d"/><path d="m18 32 10 10 19-21" stroke="#fff7dd" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
 return `<div class="picture-steps" role="img" aria-label="${type==='story'?'Read, choose, check':type==='change'?'Hear, swap a tile, check':'Hear, tap tiles, check'}"><span>${type==='story'?book:speaker}</span><i aria-hidden="true">→</i><span>${type==='change'?swap:tile}</span><i aria-hidden="true">→</i><span>${tick}</span></div>`;
}
